export type ExerciseMedia = {
  /** One or two photos. With two, they alternate to show the movement. */
  frames: string[];
  /** Source and license to show with the photos. */
  credit: string;
};

/** Photos for a library exercise, or null when neither dataset has a match. */
export function exerciseMedia(name: string): ExerciseMedia | null {
  const id = MEDIA_ID[name];
  if (id) return { frames: [`${BASE_URL}/${id}/0.jpg`, `${BASE_URL}/${id}/1.jpg`], credit: 'free-exercise-db (public domain)' };
  const w = WGER_ID[name];
  return w ? WGER[w] ?? null : null;
}
